import time

class WriteBehindCache:
    def __init__(self, storage, batch_size=10, flush_interval=5.0, clock=time.monotonic):
        self._storage = storage
        self._batch_size = batch_size
        self._flush_interval = flush_interval
        self._clock = clock
        self._cache = {}
        self._dirty = set()
        self._last_flush = self._clock()

    def put(self, key, value):
        self._cache[key] = value
        self._dirty.add(key)
        if len(self._dirty) >= self._batch_size:
            self.flush()

    def get(self, key):
        if key in self._cache:
            return self._cache[key]
        val = None
        if hasattr(self._storage, 'get'):
            val = self._storage.get(key)
        elif isinstance(self._storage, dict):
            val = self._storage.get(key)
        if val is not None:
            self._cache[key] = val
        return val

    def flush(self):
        if not self._dirty:
            return 0
        items = {k: self._cache[k] for k in self._dirty}
        if hasattr(self._storage, 'batch_write'):
            self._storage.batch_write(items)
        elif isinstance(self._storage, dict):
            self._storage.update(items)
        count = len(self._dirty)
        self._dirty.clear()
        self._last_flush = self._clock()
        return count

    def tick(self, now=None):
        current = self._clock() if now is None else now
        if (current - self._last_flush) >= self._flush_interval and self._dirty:
            return self.flush()
        return 0

    def dirty_count(self):
        return len(self._dirty)
